# RW2DM_SCALEPOS: ScalePositions: scale the distances between objects, not the objects. The script is rw2dm_scalepos_script.txt; generated by rw2dm_gen.py (the closed forms are in that file). Every object kind of the case (Point, Line, Plane, Box) is
# compared with the closed-form image of the operation: points by the residual move to the origin (printed 0,0,0 within 1e-9), curve / surface control points
# through ExtractPt the same way, boxes by their bounding box after a residual move. RW2DM_SCALEPOS_sensitivity shows that a 1e-6 error would read 1e-06.
RW2_SCALEPOS_OUT=""
rw2_scalepos_run() {
  local o
  if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
    o="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW2DM_SCALEPOS_run: $1 exited non-zero"; fail=1; o=""; }
  else
    o="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW2DM_SCALEPOS_run: $1 exited non-zero"; fail=1; o=""; }
  fi
  RW2_SCALEPOS_OUT+="$o"$'\n'
}
rw2_scalepos_run rw2dm_scalepos_script.txt
rw2_scalepos_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_SCALEPOS_OUT"; }
# rw2_scalepos_resid NAME NPTS BOXES DESC: the case listed exactly NPTS points, every one at residual 0,0,0, and the boxes' bounding boxes (joined by ';') read exactly BOXES
rw2_scalepos_resid() {
  local blk npts zeros boxes; blk="$(rw2_scalepos_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  boxes="$({ grep -E '^history: Bounding box min ' <<<"$blk" || true; } | sed -E 's/^history: Bounding box //' | paste -sd';' -)"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ] && [ "$boxes" = "$3" ]; then echo "ok   RW2DM_SCALEPOS_$1: $4 ($2 points at residual 0 within 1e-9; boxes: ${3:-none})"
  else echo "FAIL RW2DM_SCALEPOS_$1: $4 (listed $npts points, $zeros at residual 0, expected $2 and $2; boxes '$boxes', expected '$3')"; fail=1; { grep -E '^history:   |^history: Bounding box|^history: ! ' <<<"$blk" || true; } | head -16 | sed 's/^/     residual: /'; fi
}
rw2_scalepos_resid two 7 "min 0,0,0 max 2,2,2" "ScalePositions factor 2 from the origin: every object's bounding-box centre c goes to c + (c - base) = 2c, the objects keep their size (point, line, plane, box)"
rw2_scalepos_resid half 14 "min 0,0,0 max 2,2,2;min 0,0,0 max 2,2,2" "ScalePositions factor 0.5 from (2,2,0) with Copy=Yes: the originals stay, each copy's centre goes to base + 0.5 (c - base), size unchanged"
rw2_scalepos_resid neg 7 "min 0,0,0 max 2,2,2" "ScalePositions factor -1 from (1,1,0): positions are reflected through the base point, c -> 2 base - c, no object is mirrored or resized"
# negative control: the same harness must SEE a 1e-6 error (a point 1e-6 off its expected image reads 1e-06, not 0)
rw2_scalepos_sens() {
  local blk; blk="$(rw2_scalepos_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RW2DM_SCALEPOS_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RW2DM_SCALEPOS_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rw2_scalepos_sens
